function OverManegeLoungeTagNode:FreshUI(isShow, selectIndex, isChangeViewState)
    if isChangeViewState then
        self:UpdateUIShowState(isShow)
    end
    if not isShow then
        return
    end
    ---@type OverManegeLoungeDataProvider
    local dataProviderIns = DataProvider:GetInstance()
    self._dataProviderIns = dataProviderIns
    self._selectIndex = selectIndex
    self:ReloadUI(selectIndex)

end

function OverManegeLoungeTagNode:ReloadUI(selectIndex)
    local dataProviderIns = self._dataProviderIns
    local parent         = self.Lounge
    local maxLoungeCount = self._dataProviderIns:GetMaxLoungeCount()
    local forTimes = math.max(parent.childCount, maxLoungeCount)
    for i = 1, forTimes do
        local isShow = i <= maxLoungeCount
        ---@type OverManageSmallBtnLoungeNode
        local env = self._loungeNodeEnvs[i]
        local isInit = isNull(env)
        local node = self[string.format("LoungeNode%s", i)]
        KTool.SetActive(node.gameObject, isShow)
        if isInit and isShow then
            env = CfUtils.GetLuaScr(node, MaidCoffeeConstants.EnvPath.OverManageSmallBtnLoungeNode)
            self._loungeNodeEnvs[i] = env
        end

        if not isNull(env) then
            local loungeData = dataProviderIns:GetLoungeDataByIndex(i)
            if isInit then
                env:InitUI(loungeData, i, selectIndex == i)
                env:SetCallback(Bind(self, self.OnClickLoungeNodeAction))
            else
                env:FreshUI(loungeData, selectIndex == i)
            end
        end
    end
end

function OverManegeLoungeTagNode:UpdateUIShowState(isShow)
    self.OverManegeLoungeTagNode:Play(isShow and Entry or Exit)
end
