function OverManegeLoungeTagNode:OnClickLoungeNodeAction(index)
    if self._selectIndex == index then return end
    self._selectIndex = index
    Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeSwitchLounge, index)
    
    
end

--region handler

return OverManegeLoungeTagNode